def gen(rng):
    def fmt(a, k):
        return str(len(a)) + ' ' + str(k) + '\n' + ' '.join(map(str, a))
    tests = [fmt([7], 1), fmt([-7], 1), fmt([1, 2, 3], 3), fmt([5, -1, 5], 1), fmt([-1, -2, -3, -4], 2),
             fmt([0, 0, 0, 0], 2), fmt([10**9, 10**9, -10**9, 10**9], 2)]
    for n in (2, 3, 5, 8, 12, 20):
        for _ in range(3):
            hi = rng.choice([5, 20, 100])
            a = [rng.randint(-hi, hi) for _ in range(n)]
            tests.append(fmt(a, rng.randint(1, n)))
    n = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)], 50000))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)], 1))
    tests.append(fmt([rng.randint(-10**9, -1) for _ in range(n)], 99999))
    tests.append(fmt([rng.randint(10**9 - 5, 10**9) for _ in range(n)], 70000))
    return tests
